def lcs(seq1, seq2):
    m, n = len(seq1), len(seq2)
    # Create a table to store lengths of longest common subsequence.
    # dp[i][j] will hold the length of LCS of seq1[0..i-1] and seq2[0..j-1]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp table in bottom-up fashion
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if seq1[i - 1] == seq2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the longest common subsequence from the dp table
    result = []
    i, j = m, n
    while i > 0 and j > 0:
        if seq1[i - 1] == seq2[j - 1']:
            result.append(seq1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # The result list is built backwards, so reverse it
    return ''.join(reversed(result))
